// Diagnostic preload only: no test, production, assertion, timer or handle mutation.
import { createHook } from 'node:async_hooks';
import { getActiveResourcesInfo } from 'node:process';
import { writeFileSync, realpathSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { createHash } from 'node:crypto';
import { after, afterEach } from 'node:test';

const target = process.env.SOLO_HANDLE_TEST;
const destination = process.env.SOLO_HANDLE_REPORT;
const child = process.env.NODE_TEST_CONTEXT === 'child-v8' && target && process.argv.some((arg) => {
  try { return realpathSync(arg) === realpathSync(target); } catch { return false; }
});
if (child) {
  if (!destination || !resolve(destination).includes('/.cache/'))
    throw new Error('Use an explicit ignored-cache report destination.');
  const source = realpathSync(target);
  const initialSHA256 = createHash('sha256').update(readFileSync(source)).digest('hex');
  const tracked = new Map();
  const interesting = /^(Timeout|Immediate|MESSAGEPORT|MessagePort|TCPWRAP|TCPSERVERWRAP|PIPEWRAP|PROCESSWRAP|WORKER|DNSCHANNEL|UDPWRAP|SIGNALWRAP|FSEVENTWRAP|HTTPCLIENTREQUEST|GETADDRINFOREQWRAP|FSREQCALLBACK|FSREQPROMISE)$/;
  let dropped = 0;
  let recursive = false;
  const snapshots = [];
  const hook = createHook({
    init(id, type, triggerId, resource) {
      if (recursive || !interesting.test(type)) return;
      if (tracked.size >= 4096) { dropped++; return; }
      recursive = true;
      try {
        tracked.set(id, {
          id, type, triggerId, resource: new WeakRef(resource),
          stack: String(new Error('Resource creation').stack).split('\n').slice(1, 10),
        });
      } finally { recursive = false; }
    },
    destroy(id) { tracked.delete(id); },
  });
  function describe(resource) {
    let hasRef = null;
    try { if (typeof resource?.hasRef === 'function') hasRef = !!resource.hasRef(); } catch {}
    return {
      constructor: resource?.constructor?.name ?? null,
      hasRef,
      timerMilliseconds: typeof resource?._idleTimeout === 'number' ? resource._idleTimeout : null,
      callbackName: typeof resource?._onTimeout === 'function' ? resource._onTimeout.name : null,
      destroyed: typeof resource?._destroyed === 'boolean' ? resource._destroyed : null,
    };
  }
  function snapshot(reason) {
    if (snapshots.length >= 8) return;
    recursive = true;
    try {
      const rows = [...tracked.values()].slice(0, 4096).map(({ resource, ...row }) => ({
        ...row, ...describe(resource.deref()),
      }));
      snapshots.push({ at: new Date().toISOString(), reason,
        activeResourceTypes: getActiveResourcesInfo(),
        // Private API is diagnostic-only and records bounded scalar metadata.
        activeHandles: (process._getActiveHandles?.() ?? []).slice(0, 128).map(describe),
        tracked: rows, droppedResourceInitializations: dropped,
      });
      writeFileSync(destination, JSON.stringify({
        format: 'SoloOwnedTestHandleDiagnosticV1', source, initialSHA256,
        finalSHA256: createHash('sha256').update(readFileSync(source)).digest('hex'),
        node: process.version, pid: process.pid, snapshots,
        scope: 'Diagnostic instrumentation only. No handle is closed/unrefed and no canonical deadline/assertion is changed. This is not a passing full-file receipt or timing evidence.',
      }, null, 2) + '\n');
    } finally { recursive = false; }
  }
  hook.enable();
  let completedCases = 0;
  afterEach(() => {
    if (++completedCases !== 15) return;
    snapshot('after-fifteenth-case-hook');
    const timer = setTimeout(() => snapshot('three-seconds-after-fifteenth-case'), 3000);
    timer.unref();
  });
  after(() => {
    snapshot('root-after-all-test-hooks');
    // This observer cannot keep an otherwise finished process alive.
    const timer = setTimeout(() => snapshot('three-seconds-after-root-after'), 3000);
    timer.unref();
  });
  process.on('beforeExit', () => snapshot('beforeExit'));
  process.on('exit', () => snapshot('exit'));
}
